import type { CoverScene } from "@/components/visuals/glyph/cover-scenes";
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from "@/components/visuals/dot-engine/dot-morph-dots";
import { clearGooField, createGooField, fuseGooField, readGooField } from "@/components/visuals/dot-engine/dot-morph-goo";
import type { DotMorphFrame } from "@/components/visuals/dot-engine/dot-morph-player";

/**
 * Ported from context-website (agencidev/landing-page): src/components/sections/home/blog-cover-dot-shader.ts.
 *
 * The Context Dot Shader from scripts/blog-cover-art/dot-shader.mjs, run live: a scene is drawn small, each grid cell's
 * coverage and tone are read back, and every cell becomes a filled dot, a hollow dot or nothing. The constants below
 * mirror the script's, so a scene held still lands on the same dots as the generated cover.
 */

export const COVER_GRID: DotGrid = { columns: 80, rows: 60, pitch: 10, dotRadius: 3.4, ringStroke: 1.6, haloRadius: 16 };
const CELL_COUNT = COVER_GRID.columns * COVER_GRID.rows;

const TONE_AMOUNT = 0.75;
const CONTRAST = 2.2;
const DITHER = 0.22;
const TEXTURE = 0.12;
const FILLED_AT = 0.55;
const HOLLOW_AT = 0.16;
const MIN_COVERAGE = 0.08;

// The canvas anti-aliases every pixel into its true area coverage, so two samples a side already measure a cell exactly.
const SAMPLES_PER_CELL = 2;
const FIELD_WIDTH = COVER_GRID.columns * SAMPLES_PER_CELL;
const FIELD_HEIGHT = COVER_GRID.rows * SAMPLES_PER_CELL;
const FIELD_SCALE = SAMPLES_PER_CELL / COVER_GRID.pitch;

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map((value) => (value + 0.5) / 16);

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

function hashNoise(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return n - Math.floor(n);
}

function smoothNoise(x: number, y: number) {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const fx = x - x0;
  const fy = y - y0;
  const sx = fx * fx * (3 - 2 * fx);
  const sy = fy * fy * (3 - 2 * fy);
  const top = hashNoise(x0, y0) + (hashNoise(x0 + 1, y0) - hashNoise(x0, y0)) * sx;
  const bottom = hashNoise(x0, y0 + 1) + (hashNoise(x0 + 1, y0 + 1) - hashNoise(x0, y0 + 1)) * sx;
  return top + (bottom - top) * sy;
}

const CELL_TEXTURE = new Float32Array(CELL_COUNT);
const CELL_DITHER = new Float32Array(CELL_COUNT);
for (let row = 0; row < COVER_GRID.rows; row++) {
  for (let column = 0; column < COVER_GRID.columns; column++) {
    CELL_TEXTURE[row * COVER_GRID.columns + column] = (smoothNoise(column / 3.2, row / 3.2) - 0.5) * TEXTURE;
    CELL_DITHER[row * COVER_GRID.columns + column] = (BAYER[(row & 3) * 4 + (column & 3)] - 0.5) * DITHER * 0.5;
  }
}

function classify(cell: number, coverage: number, tone: number) {
  if (coverage < MIN_COVERAGE) return DOT_ABSENT;
  const contrasted = clamp01((tone - 0.5) * CONTRAST + 0.5);
  const value = Math.sqrt(coverage) * (1 - TONE_AMOUNT * (1 - clamp01(contrasted + CELL_TEXTURE[cell]))) + CELL_DITHER[cell];
  if (value >= FILLED_AT) return DOT_FILLED;
  return value >= HOLLOW_AT ? DOT_HOLLOW : DOT_ABSENT;
}

/**
 * Reads a generated cover back into one dot state per grid cell: each path command is a row of neighboring dots.
 * `picture` is the cover itself, or the picture it melts into on hover, which the file carries undrawn.
 */
export function parseCoverDots(svg: string, picture: "cover" | "morph" = "cover"): Uint8Array {
  const states = new Uint8Array(CELL_COUNT);
  const prefix = picture === "morph" ? "morph-" : "";
  for (const [id, state] of [
    ["filled", DOT_FILLED],
    ["hollow", DOT_HOLLOW],
  ] as const) {
    const runs = new RegExp(`id="${prefix}${id}"[^>]* d="([^"]*)"`).exec(svg)?.[1] ?? "";
    for (const run of runs.matchAll(/M([\d.]+) ([\d.]+)h([\d.]+)/g)) {
      const first = Math.floor(Number(run[2]) / COVER_GRID.pitch) * COVER_GRID.columns + Math.floor(Number(run[1]) / COVER_GRID.pitch);
      states.fill(state, first, first + Math.floor(Number(run[3]) / COVER_GRID.pitch) + 1);
    }
  }
  return states;
}

export function createCoverShader(scene: CoverScene) {
  const goo = createGooField(FIELD_WIDTH, FIELD_HEIGHT);
  const crisp = createGooField(FIELD_WIDTH, FIELD_HEIGHT);
  const scratch = new Float32Array(FIELD_WIDTH * FIELD_HEIGHT);
  const states = new Uint8Array(CELL_COUNT);
  // A scene is drawn from the morph and spin alone, so a frame that repeats both (a held or unspun cover) is unchanged.
  let lastMorph = Number.NaN;
  let lastSpin = Number.NaN;

  return (frame: DotMorphFrame) => {
    if (frame.morph === lastMorph && frame.spin === lastSpin) return states;
    lastMorph = frame.morph;
    lastSpin = frame.spin;
    clearGooField(goo, FIELD_SCALE);
    clearGooField(crisp, FIELD_SCALE);
    scene.draw({ goo: goo.context, crisp: crisp.context }, frame);
    readGooField(goo);
    readGooField(crisp);

    const sigma = scene.gooSigma(frame.morph) * FIELD_SCALE;
    if (sigma > 0.002) fuseGooField(goo, scratch, sigma);

    for (let row = 0; row < COVER_GRID.rows; row++) {
      for (let column = 0; column < COVER_GRID.columns; column++) {
        let coverage = 0;
        let darkness = 0;
        for (let sampleY = 0; sampleY < SAMPLES_PER_CELL; sampleY++) {
          const rowStart = (row * SAMPLES_PER_CELL + sampleY) * FIELD_WIDTH + column * SAMPLES_PER_CELL;
          for (let sampleX = 0; sampleX < SAMPLES_PER_CELL; sampleX++) {
            const pixel = rowStart + sampleX;
            const showsThrough = 1 - crisp.coverage[pixel];
            coverage += crisp.coverage[pixel] + goo.coverage[pixel] * showsThrough;
            darkness += crisp.darkness[pixel] + goo.darkness[pixel] * showsThrough;
          }
        }
        const cell = row * COVER_GRID.columns + column;
        states[cell] = coverage > 0 ? classify(cell, coverage / (SAMPLES_PER_CELL * SAMPLES_PER_CELL), darkness / coverage) : DOT_ABSENT;
      }
    }
    return states;
  };
}

import { COVER_GRID, createCoverShader, parseCoverDots } from "@/components/visuals/glyph/cover-dot-shader";
import { pagesScene } from "@/components/visuals/glyph/cover-scenes";
import type { DotPalette } from "@/components/visuals/dot-engine/dot-morph-dots";
import { createDotMorphPlayer, type DotMorphFrame, type DotMorphPlayer } from "@/components/visuals/dot-engine/dot-morph-player";
import { PAGES_COVER_SVG } from "@/components/visuals/glyph/pages-cover-art";

// Bolder dots than the website's covers (radius 3.4, ring 1.6), so the art reads as solid brand blue at card size like the
// glyphs beside it. The cover art is drawn to match, so the resting art and the live morph line up.
const DASHBOARD_COVER_GRID = { ...COVER_GRID, dotRadius: 3.8, ringStroke: 2 };

interface CoverMorphOptions {
  canvas: HTMLCanvasElement;
  palette: DotPalette;
  onPlayingChange: (isPlaying: boolean) => void;
  onFrame?: (frame: DotMorphFrame) => void;
}

/** The website's "pages" blog cover, live: it rests on the generated art and plays the scene's morph from there. */
export function createPagesCoverMorph({ canvas, palette, onPlayingChange, onFrame }: CoverMorphOptions): DotMorphPlayer {
  return createDotMorphPlayer({
    canvas,
    palette,
    onPlayingChange,
    onFrame,
    source: {
      grid: DASHBOARD_COVER_GRID,
      fit: "contain",
      restingDots: parseCoverDots(PAGES_COVER_SVG),
      spinSpeed: pagesScene.spinSpeed,
      spinPeriod: pagesScene.spinPeriod,
      sample: createCoverShader(pagesScene),
    },
  });
}

import type { DotMorphFrame } from "@/components/visuals/dot-engine/dot-morph-player";

/**
 * The "pages" blog cover's hover choreography, ported from context-website (agencidev/landing-page):
 * src/components/sections/home/blog-cover-scenes.ts. At `morph` 0 it draws the shaded illustration behind
 * public/blog-covers/pages.svg (keep the two in step), and by `morph` 1 the three pages have bound into one. `spin` keeps
 * the big page's lines writing while it holds.
 *
 * Shapes on the goo layer are blurred and re-cut by the dot shader, so they melt into each other as they meet; the crisp
 * layer is for line work that must survive that.
 */

type Context = CanvasRenderingContext2D;

export interface CoverLayers {
  goo: Context;
  crisp: Context;
}

export interface CoverScene {
  spinSpeed: number;
  spinPeriod: number;
  /** Blur, in cover units, that fuses the goo layer's shapes. */
  gooSigma: (morph: number) => number;
  draw: (layers: CoverLayers, frame: DotMorphFrame) => void;
}

const TAU = Math.PI * 2;
const CENTER_X = 400;
const CENTER_Y = 300;

// The scene is drawn on an offscreen raster that the dot shader reads back as coverage and tone; it is never shown, so
// its black, white and grays are shading amounts (black a filled dot, white a ring), not colors.
const shade = (level: number) => "rgb(" + [level, level, level].join(" ") + ")";
const PAGE_LIT = "white";
const PAGE_SHADED = shade(208);
const INK = "black";

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const lerp = (from: number, to: number, amount: number) => from + (to - from) * amount;
const phase = (morph: number, start: number, end: number) => clamp01((morph - start) / (end - start));
const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);
const easeOutBack = (t: number) => 1 + 2.70158 * (t - 1) ** 3 + 1.70158 * (t - 1) ** 2;
const swell = (morph: number, start: number, end: number) => Math.sin(Math.PI * phase(morph, start, end));

function linearFill(context: Context, x0: number, y0: number, x1: number, y1: number, from: string, to: string) {
  const gradient = context.createLinearGradient(x0, y0, x1, y1);
  gradient.addColorStop(0, from);
  gradient.addColorStop(1, to);
  return gradient;
}

interface TextLine {
  y: number;
  width: number;
  height: number;
}

function drawPage(context: Context, width: number, height: number, border: number, inset: number, lines: TextLine[]) {
  const left = -width / 2;
  const top = -height / 2;
  context.fillStyle = linearFill(context, left, top, -left, -top, PAGE_LIT, PAGE_SHADED);
  context.fillRect(left, top, width, height);
  context.fillStyle = INK;
  for (const line of lines) context.fillRect(left + inset, top + line.y, line.width, line.height);
  context.strokeStyle = INK;
  context.lineWidth = border;
  context.strokeRect(left, top, width, height);
}

const smallPageLines = (widths: number[]): TextLine[] => widths.map((width, index) => ({ y: 40 + index * 40, width, height: 20 }));

const SMALL_PAGES = [
  { x: 163, y: 310, rotate: -5, lines: smallPageLines([96, 114, 78, 108, 88]) },
  { x: 400, y: 285, rotate: 0, lines: smallPageLines([114, 82, 114, 100, 70]) },
  { x: 637, y: 310, rotate: 5, lines: smallPageLines([104, 80, 114, 74, 100]) },
];

const BIG_PAGE_LINES: TextLine[] = [
  { y: 48, width: 150, height: 30 },
  { y: 110, width: 230, height: 20 },
  { y: 152, width: 196, height: 20 },
  { y: 194, width: 230, height: 20 },
  { y: 236, width: 168, height: 20 },
  { y: 278, width: 214, height: 20 },
  { y: 320, width: 186, height: 20 },
  { y: 362, width: 120, height: 20 },
];

// The outer pages stop this far short of the center, so the three fuse into one wide mass rather than a single stack.
const GATHERED_SPREAD = 0.3;

/** Three pages gather and bind into one big page whose lines keep writing while the card stays hovered. */
export const pagesScene: CoverScene = {
  spinSpeed: 1.5,
  spinPeriod: TAU,
  gooSigma: (morph) => 18 * swell(morph, 0.05, 0.95),
  draw({ goo }, { morph, spin }) {
    const gather = easeInOut(phase(morph, 0, 0.6));
    const bind = easeInOut(phase(morph, 0.3, 0.75));

    goo.globalAlpha = 1 - bind;
    for (const page of SMALL_PAGES) {
      goo.save();
      goo.translate(lerp(page.x, lerp(CENTER_X, page.x, GATHERED_SPREAD), gather), lerp(page.y, CENTER_Y, gather));
      goo.rotate((lerp(page.rotate, 0, gather) * Math.PI) / 180);
      drawPage(goo, 170, 250, 12, 28, page.lines);
      goo.restore();
    }

    const writing = easeInOut(phase(morph, 0.8, 1));
    const size = lerp(0.6, 1, easeOutBack(phase(morph, 0.35, 0.95)));
    goo.globalAlpha = bind;
    goo.save();
    goo.translate(CENTER_X, CENTER_Y);
    goo.scale(size, size);
    drawPage(
      goo,
      310,
      430,
      14,
      40,
      BIG_PAGE_LINES.map((line, index) => (index === 0 ? line : { ...line, width: line.width * (1 + 0.14 * writing * Math.sin(spin + index * 1.3)) })),
    );
    goo.restore();
    goo.globalAlpha = 1;
  },
};

import type { GlyphCell } from "@/components/visuals/dot-engine/dot-glyph-cells";
import { createBeatStoryPlayer, type StoryPicture } from "@/components/visuals/dot-engine/dot-story-beats";
import { cellStates, cellsOfStates } from "@/components/visuals/dot-engine/dot-story-cells";
import type { DotStoryPlayer, DotStoryStage } from "@/components/visuals/dot-engine/dot-story-player";
import { GLYPH_GRID, glyphOutcome, glyphSubject, type GlyphPairName } from "@/components/visuals/glyph/glyph-art";

// A glyph this small is mostly one-dot lines, which a melt thins to nothing halfway through; a wave from the
// middle swaps one glyph for the other without ever emptying the picture.
const WAVE = { seconds: 0.8, origin: { column: 5, row: 5 } };
const OUTCOME_HOLD_SECONDS = 2.2;
const SUBJECT_HOLD_SECONDS = 2.8;

const pictureOfCells = (cells: GlyphCell[]): StoryPicture => {
  const states = cellStates(GLYPH_GRID, cells);
  return { states, cells: cellsOfStates(GLYPH_GRID, states) };
};

/** `startsAtSeconds` into the subject's hold is where this picture joins the loop, so neighbors don't melt in step. */
export function createGlyphLoopPlayer(stage: DotStoryStage, name: GlyphPairName, startsAtSeconds = 0): DotStoryPlayer {
  return createBeatStoryPlayer(stage, {
    grid: GLYPH_GRID,
    resting: { beat: 1, heldSeconds: startsAtSeconds % SUBJECT_HOLD_SECONDS },
    beats: [
      { picture: pictureOfCells(glyphOutcome(name)), arrival: { kind: "waves", ...WAVE }, holdSeconds: OUTCOME_HOLD_SECONDS },
      { picture: pictureOfCells(glyphSubject(name)), arrival: { kind: "waves", ...WAVE }, holdSeconds: SUBJECT_HOLD_SECONDS },
    ],
  });
}

import { createGlyphShader, drawGlyphCells, glyphRestingDots, type GlyphMorph } from "@/components/visuals/dot-engine/dot-glyph-morph";
import type { DotPalette } from "@/components/visuals/dot-engine/dot-morph-dots";
import { createDotMorphPlayer, type DotMorphPlayer } from "@/components/visuals/dot-engine/dot-morph-player";
import { GLYPH_GRID, GLYPH_MELT_MARGIN, glyphOutcome, glyphSubject, type GlyphPairName } from "@/components/visuals/glyph/glyph-art";
import { GLYPH_HOLDS } from "@/components/visuals/glyph/glyph-melt-holds";

/**
 * The blog covers' hover melt, played on a page glyph: its subject blurs and re-cuts into what it gives you, then
 * eases back when let go. A pair with a hold keeps moving while the card stays hovered. The grid reaches a few cells
 * past the glyph, so the melt can spill over its edge.
 */

// The covers' melt blurs a cell and a half, which thins a glyph's one-dot lines to nothing halfway through; a lighter
// blur, keeping any dot the melt even a fifth covers, carries the picture across without ever emptying it.
const GOO_SIGMA_IN_CELLS = 0.6;
const PRESENT_AT = 0.2;

const GLYPH_MELT_GRID = { ...GLYPH_GRID, columns: GLYPH_GRID.columns + GLYPH_MELT_MARGIN * 2, rows: GLYPH_GRID.rows + GLYPH_MELT_MARGIN * 2 };

interface GlyphMeltOptions {
  canvas: HTMLCanvasElement;
  name: GlyphPairName;
  palette: DotPalette;
  onPlayingChange: (isPlaying: boolean) => void;
}

export function createGlyphMelt({ canvas, name, palette, onPlayingChange }: GlyphMeltOptions): DotMorphPlayer {
  const outcome = glyphOutcome(name);
  const hold = GLYPH_HOLDS[name];
  const morph: GlyphMorph = {
    grid: GLYPH_MELT_GRID,
    box: { left: GLYPH_MELT_MARGIN, top: GLYPH_MELT_MARGIN, cellsPerSide: GLYPH_GRID.columns },
    cells: glyphSubject(name),
    drawTarget: (context, { spin }) => (hold ? hold.draw(context, spin) : drawGlyphCells(context, outcome, GLYPH_GRID.pitch)),
    gooSigmaInCells: GOO_SIGMA_IN_CELLS,
    presentAt: PRESENT_AT,
  };

  return createDotMorphPlayer({
    canvas,
    palette,
    onPlayingChange,
    source: {
      grid: GLYPH_MELT_GRID,
      fit: "contain",
      restingDots: glyphRestingDots(morph),
      // Without a hold nothing keeps moving once the outcome has arrived, so there is no spin to rewind.
      spinSpeed: hold?.spinSpeed ?? 0,
      spinPeriod: hold?.spinPeriod ?? Math.PI * 2,
      sample: createGlyphShader(morph),
    },
  });
}

import { glyphCellsFromRows } from "@/components/visuals/dot-engine/dot-glyph-cells";
import { drawGlyphCells } from "@/components/visuals/dot-engine/dot-glyph-morph";
import { GLYPH_GRID, type GlyphPairName } from "@/components/visuals/glyph/glyph-art";

/**
 * What keeps moving once a glyph has melted into its outcome, for as long as its card stays hovered, as the blog
 * covers' holds do. A hold draws the outcome itself, in grid units from the glyph box's top-left corner: black draws
 * filled dots, white hollow ones. Pairs without one simply rest on their outcome glyph.
 */

export interface GlyphHold {
  spinSpeed: number;
  /** The motion repeats every this many radians of spin. */
  spinPeriod: number;
  draw: (context: CanvasRenderingContext2D, spin: number) => void;
}

const TAU = Math.PI * 2;
const { pitch, columns } = GLYPH_GRID;
const CENTER = (columns * pitch) / 2;

const fillDisc = (context: CanvasRenderingContext2D, x: number, y: number, radius: number) => {
  context.beginPath();
  context.arc(x, y, radius, 0, TAU);
  context.fill();
};

// A smaller globe than the outcome glyph's, so its orbits have room to swing round it inside the melt's margin.
const SMALL_GLOBE = glyphCellsFromRows(["  ###  ", " # # # ", "#  #  #", "#######", "#  #  #", " # # # ", "  ###  "]).map((cell) => ({
  ...cell,
  column: cell.column + 2,
  row: cell.row + 2,
}));
const ORBITS = 3;
const ORBIT_REACH = 66;
const ORBIT_DEPTH = 22;
const ORBIT_STROKE = 6;
// The orbits pass behind the globe: a ring this wide round it is cleared before the globe is drawn.
const GLOBE_CLEARANCE = 44;
const SATELLITE_RADIUS = 8;
// The orbits are a sixth of a turn apart, so the set looks the same each time it has turned that far.
const ORBIT_TURN_PER_SPIN = 1 / 6;

/** Three hollow orbits turn round a small globe, each carrying a satellite. */
const orbitingGlobe: GlyphHold = {
  spinSpeed: 3,
  spinPeriod: TAU,
  draw(context, spin) {
    const turn = spin * ORBIT_TURN_PER_SPIN;
    context.strokeStyle = "white";
    context.lineWidth = ORBIT_STROKE;
    for (let orbit = 0; orbit < ORBITS; orbit++) {
      context.beginPath();
      context.ellipse(CENTER, CENTER, ORBIT_REACH, ORBIT_DEPTH, turn + (orbit / ORBITS) * Math.PI, 0, TAU);
      context.stroke();
    }
    context.fillStyle = "black";
    for (let orbit = 0; orbit < ORBITS; orbit++) {
      const tilt = turn + (orbit / ORBITS) * Math.PI;
      const along = spin + (orbit / ORBITS) * TAU;
      const x = Math.cos(along) * ORBIT_REACH;
      const y = Math.sin(along) * ORBIT_DEPTH;
      fillDisc(context, CENTER + x * Math.cos(tilt) - y * Math.sin(tilt), CENTER + x * Math.sin(tilt) + y * Math.cos(tilt), SATELLITE_RADIUS);
    }
    context.globalCompositeOperation = "destination-out";
    fillDisc(context, CENTER, CENTER, GLOBE_CLEARANCE);
    context.globalCompositeOperation = "source-over";
    drawGlyphCells(context, SMALL_GLOBE, pitch);
  },
};

export const GLYPH_HOLDS: Partial<Record<GlyphPairName, GlyphHold>> = {
  dataApis: orbitingGlobe,
};

import { createBeatStoryPlayer, type StoryPicture } from "@/components/visuals/dot-engine/dot-story-beats";
import { cellStates, cellsOfStates } from "@/components/visuals/dot-engine/dot-story-cells";
import type { DotStoryPlayer, DotStoryStage } from "@/components/visuals/dot-engine/dot-story-player";
import { GLYPH_GRID, glyphOutcome, glyphSubject, type GlyphPairName } from "@/components/visuals/glyph/glyph-art";
import { FINE_GRID, fineStates } from "@/components/visuals/glyph/upgrade-story-fine";

const MELT = { kind: "melts" as const, seconds: 0.9 };

const pictureOf = (cells: ReturnType<typeof glyphSubject>): StoryPicture => {
  const states = fineStates(cellStates(GLYPH_GRID, cells));
  return { states, cells: cellsOfStates(FINE_GRID, states) };
};

/** A glyph pair told as the upgrade card tells its story: the subject melts into what it gives you, and back. */
export function createGlyphStoryPlayer(stage: DotStoryStage, name: GlyphPairName): DotStoryPlayer {
  return createBeatStoryPlayer(stage, {
    grid: FINE_GRID,
    resting: { beat: 0, heldSeconds: 0 },
    beats: [
      { picture: pictureOf(glyphSubject(name)), arrival: MELT, holdSeconds: 1.8 },
      { picture: pictureOf(glyphOutcome(name)), arrival: MELT, holdSeconds: 1.8 },
    ],
  });
}

/**
 * The color a dot picture repaints around its dots. It defaults to the theme's surface token, which SVG can use as is;
 * a canvas can't read CSS variables, so `resolveColor` turns `var(--token)` into the color it currently stands for.
 */
export const SURFACE_COLOR = "var(--ds-color-bg-default)";

export function resolveColor(element: Element, color: string) {
  const token = /^var\((--[\w-]+)\)$/.exec(color)?.[1];
  return token ? getComputedStyle(element).getPropertyValue(token).trim() || color : color;
}

import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from "@/components/visuals/dot-engine/dot-morph-dots";
import { cellsOfStates } from "@/components/visuals/dot-engine/dot-story-cells";
import { GLYPH_GRID } from "@/components/visuals/glyph/glyph-art";

/**
 * The upgrade story drawn in the blog covers' fine dot pattern, like the Browse APIs card beside it: every dot of the
 * 11 × 11 glyph becomes a 4 × 4 block of small dots. A solid dot's block is mostly filled with a scatter of rings, as
 * the covers shade a solid surface; a ring's block is all rings.
 */

const SCALE = 4;

export const FINE_GRID: DotGrid = {
  columns: GLYPH_GRID.columns * SCALE,
  rows: GLYPH_GRID.rows * SCALE,
  pitch: 10,
  dotRadius: 3.8,
  ringStroke: 2,
  haloRadius: 0,
};

// Which small dots of a solid block are rings: one in four, staggered row to row so they read as texture, not stripes.
const isRingInSolid = (column: number, row: number) => (column + 2 * row) % 4 === 0;

/** A glyph-grid picture's states at the fine grid's size. */
export function fineStates(coarse: Uint8Array): Uint8Array {
  const fine = new Uint8Array(FINE_GRID.columns * FINE_GRID.rows);
  for (let row = 0; row < GLYPH_GRID.rows; row++) {
    for (let column = 0; column < GLYPH_GRID.columns; column++) {
      const state = coarse[row * GLYPH_GRID.columns + column];
      if (state === DOT_ABSENT) continue;
      for (let dy = 0; dy < SCALE; dy++) {
        for (let dx = 0; dx < SCALE; dx++) {
          const fineColumn = column * SCALE + dx;
          const fineRow = row * SCALE + dy;
          fine[fineRow * FINE_GRID.columns + fineColumn] = state === DOT_FILLED && !isRingInSolid(fineColumn, fineRow) ? DOT_FILLED : DOT_HOLLOW;
        }
      }
    }
  }
  return fine;
}

export const fineCellsOf = (coarse: Uint8Array) => cellsOfStates(FINE_GRID, fineStates(coarse));

import type { GlyphCell } from "@/components/visuals/dot-engine/dot-glyph-cells";
import { createBeatStoryPlayer, type StoryPicture } from "@/components/visuals/dot-engine/dot-story-beats";
import { cellStates, cellsOfStates } from "@/components/visuals/dot-engine/dot-story-cells";
import type { DotStoryPlayer, DotStoryStage } from "@/components/visuals/dot-engine/dot-story-player";
import { GLYPH_GRID } from "@/components/visuals/glyph/glyph-art";
import { FINE_GRID, fineStates } from "@/components/visuals/glyph/upgrade-story-fine";
import { GIFT_CELLS, ROCKET_CELLS } from "@/components/visuals/glyph/upgrade-story-art";

const MELT = { kind: "melts" as const, seconds: 0.9 };

// Pictures are drawn on the glyph grid and played on the fine one (see upgrade-story-fine).
const pictureOfCells = (cells: GlyphCell[]): StoryPicture => {
  const states = fineStates(cellStates(GLYPH_GRID, cells));
  return { states, cells: cellsOfStates(FINE_GRID, states) };
};

/** A gift that becomes a rocket, which melts back into the gift. */
export function createUpgradeStoryPlayer(stage: DotStoryStage): DotStoryPlayer {
  return createBeatStoryPlayer(stage, {
    grid: FINE_GRID,
    resting: { beat: 0, heldSeconds: 0 },
    beats: [
      { picture: pictureOfCells(GIFT_CELLS), arrival: MELT, holdSeconds: 1.6 },
      { picture: pictureOfCells(ROCKET_CELLS), arrival: MELT, holdSeconds: 2 },
    ],
  });
}
